import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total = sc.nextInt();
        int select = sc.nextInt();
        double[] probs = new double[total];
        for (int i = 0; i < total; i++) {
            probs[i] = sc.nextDouble();
        }

        int positiveCount = 0;
        for (double p : probs) {
            if (p > 1e-6) positiveCount++;
        }

        if (positiveCount <= select) {
            for (double p : probs) {
                System.out.print((p > 1e-6 ? "1 " : "0 "));
            }
            System.out.println();
            return;
        }

        double[] result = new double[total];
        int size = 1 << total;
        double[] dp = new double[size];
        dp[0] = 1.0;

        for (int mask = 0; mask < size; mask++) {
            double sumProb = 0.0;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) {
                    sumProb += probs[i];
                }
            }
            if (sumProb >= 0.99999) continue;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int nextMask = mask | (1 << i);
                dp[nextMask] += dp[mask] * probs[i] / (1 - sumProb);
            }
        }

        for (int mask = 0; mask < size; mask++) {
            int countBits = Integer.bitCount(mask);
            if (countBits != select) continue;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) {
                    result[i] += dp[mask];
                }
            }
        }

        System.out.printf(Locale.US, "%.13f", 0.0);
        for (double v : result) {
            System.out.print(v + " ");
        }
        System.out.println();
    }
}
